from __future__ import annotations
from typing import List

def square_sum(a: int, b: int) -> int:
    return a * a + b * b

def decompose_into_squares(n: int) -> List[List[int]]:
    solutions = []
    for e in range(int(n ** 0.5) + 1):
        f_squared = n - e ** 2
        f = int(f_squared ** 0.5)
        if f_squared == f ** 2:
            solutions.append([min(e, f), max(e, f)])
    return sorted(solutions)

def product_of_squares(a: int, b: int, c: int, d: int) -> int:
    sum1 = square_sum(a, b)
    sum2 = square_sum(c, d)
    product = sum1 * sum2
    return product

def prod2sum(a: int, b: int, c: int, d: int) -> List[List[int]]:
    n = (a ** 2 + b ** 2) * (c ** 2 + d ** 2)
    decomposed = decompose_into_squares(n)
    result = []
    for e, f in decomposed:
        if e <= f:
            result.append([e, f])
    return result

